//! The kit lock (notes: kit-plan.md section 3): only the kit draws, the kit cites the design,
//! generated files are untouched. Shell `.slint` files (everything outside `ui/kit/`) compose
//! kit components; they may not paint, animate, set fonts, write `Text` directly, name a design
//! token group or write a literal. Kit files (`ui/kit/**` but `gen/`) start with a `design:` or
//! `derived:` header, and take every value from the generated files. The generated files carry
//! the design commit and a hash of their body.
//!
//! Today's violations are recorded in `kit_lock_baseline.txt` (file, rule, token, count): the
//! test fails on any count above its baseline (a new violation) and on any count below it (the
//! baseline must be lowered with the fix). `KIT_LOCK_WRITE=1 cargo test -p wubble-ui --test
//! kit_lock` rewrites the baseline, but only when no count went up: it can only shrink.
//!
//! Pure string scans; no timing.

use std::collections::BTreeMap;
use std::fs;
use std::path::{Path, PathBuf};

/// Violations counted per (file, rule, token).
type Counts = BTreeMap<(String, String, String), usize>;

fn ui_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("ui")
}

fn repo() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn files(dir: &Path, ext: &str, out: &mut Vec<PathBuf>) {
    for entry in fs::read_dir(dir).expect("read dir") {
        let path = entry.expect("dir entry").path();
        if path.is_dir() {
            files(&path, ext, out);
        } else if path.extension().is_some_and(|e| e == ext) {
            out.push(path);
        }
    }
}

/// Every `.slint` file, as (path relative to `ui/`, text).
fn ui_files() -> Vec<(String, String)> {
    let mut paths = Vec::new();
    files(&ui_dir(), "slint", &mut paths);
    assert!(!paths.is_empty(), "no slint files found");
    paths.sort();
    paths
        .into_iter()
        .map(|p| {
            let rel = p
                .strip_prefix(ui_dir())
                .expect("under ui")
                .to_string_lossy();
            (
                rel.replace('\\', "/"),
                fs::read_to_string(&p).expect("read"),
            )
        })
        .collect()
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Kind {
    /// Composes kit components only.
    Shell,
    /// A kit component or derived token file: may draw, must cite, takes values from `gen/`.
    Kit,
    /// Generated by `tools/fidelity/extract.mjs`.
    Generated,
    /// The design port's token copy (`ui/tokens.slint`), replaced by `gen/tokens.slint` in L2.
    LegacyTokens,
}

fn kind(rel: &str) -> Kind {
    if rel.starts_with("kit/gen/") {
        Kind::Generated
    } else if rel.starts_with("kit/") {
        Kind::Kit
    } else if rel == "tokens.slint" {
        Kind::LegacyTokens
    } else {
        Kind::Shell
    }
}

/// One line with `//` comments and string contents blanked out.
fn code(line: &str) -> String {
    let mut quoted = false;
    let mut out = String::new();
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        if !quoted && c == '/' && chars.peek() == Some(&'/') {
            break;
        }
        if c == '"' {
            quoted = !quoted;
            out.push(c);
        } else {
            out.push(if quoted { ' ' } else { c });
        }
    }
    out
}

/// The literals in one line of code: non-zero `px`/`ms`/`s` numbers, `#hex`, colour functions.
fn literals(line: &str) -> Vec<String> {
    let code = code(line);
    let chars: Vec<char> = code.chars().collect();
    let mut found = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '#' && chars.get(i + 1).is_some_and(|n| n.is_ascii_hexdigit()) {
            found.push(
                chars[i..]
                    .iter()
                    .copied()
                    .enumerate()
                    .take_while(|(k, h)| *k == 0 || h.is_ascii_hexdigit())
                    .map(|(_, h)| h)
                    .collect(),
            );
        }
        let starts_number = c.is_ascii_digit()
            && (i == 0 || !(chars[i - 1].is_alphanumeric() || matches!(chars[i - 1], '_' | '-')));
        if starts_number {
            let mut j = i;
            while j < chars.len() && (chars[j].is_ascii_digit() || chars[j] == '.') {
                j += 1;
            }
            let number: String = chars[i..j].iter().collect();
            let unit: String = chars[j..]
                .iter()
                .take_while(|u| u.is_alphabetic())
                .collect();
            let is_zero = number.chars().all(|d| d == '0' || d == '.');
            if matches!(unit.as_str(), "px" | "ms" | "s") && !is_zero {
                found.push(format!("{number}{unit}"));
            }
            i = j;
            continue;
        }
        i += 1;
    }
    for call in ["rgb(", "rgba(", "hsl(", "hsla("] {
        found.extend(std::iter::repeat_n(
            call.to_string(),
            code.matches(call).count(),
        ));
    }
    found
}

/// The shell rules a line breaks, as (rule, token).
fn shell_violations(line: &str) -> Vec<(&'static str, String)> {
    let code = code(line);
    let mut out: Vec<(&'static str, String)> =
        literals(line).into_iter().map(|l| ("literal", l)).collect();
    // a property set: `name:` at the start of a statement (after `{`, `;` or `}`)
    for statement in code.split(['{', ';', '}']) {
        let Some((name, _)) = statement.split_once(':') else {
            continue;
        };
        let name = name.trim();
        if name.is_empty()
            || name.contains(|c: char| !(c.is_alphanumeric() || c == '-' || c == '_'))
        {
            continue;
        }
        let painted = matches!(
            name,
            "background"
                | "border-color"
                | "border-width"
                | "fill"
                | "stroke"
                | "stroke-width"
                | "colorize"
        ) || name.starts_with("drop-shadow-");
        if painted {
            out.push(("paint", name.to_string()));
        }
        if matches!(name, "font-size" | "font-weight" | "font-family") {
            out.push(("font", name.to_string()));
        }
        if name == "commands" {
            out.push(("primitive", "commands".into()));
        }
    }
    for gradient in ["@linear-gradient", "@radial-gradient"] {
        for _ in code.matches(gradient) {
            out.push(("paint", gradient.into()));
        }
    }
    let words: Vec<&str> = code
        .split(|c: char| !(c.is_alphanumeric() || c == '-' || c == '_' || c == '.' || c == '{'))
        .collect();
    for (i, w) in words.iter().enumerate() {
        if *w == "animate" {
            out.push(("animate", "animate".into()));
        }
        let next_is_block = || words[i + 1..].iter().find(|w| !w.is_empty()) == Some(&"{");
        if (*w == "Text" || *w == "Text{") && (w.ends_with('{') || next_is_block()) {
            out.push(("text", "Text".into()));
        }
        if (*w == "Path" || *w == "Path{") && (w.ends_with('{') || next_is_block()) {
            out.push(("primitive", "Path".into()));
        }
        for group in [
            "Palette", "Glass", "Motion", "Type", "Radius", "Fonts", "Spaces",
        ] {
            if w.starts_with(group) && w[group.len()..].starts_with('.') {
                out.push(("token", group.into()));
            }
        }
    }
    out
}

/// The header lines a kit file must start with.
fn provenance(rel: &str, text: &str, design: Option<&Path>) -> Result<(), String> {
    let head: Vec<&str> = text.lines().take(3).collect();
    let cite = head
        .iter()
        .find_map(|l| l.strip_prefix("// design: ").map(|c| ("design", c)))
        .or_else(|| {
            head.iter()
                .find_map(|l| l.strip_prefix("// derived: ").map(|c| ("derived", c)))
        });
    let Some((how, cite)) = cite else {
        return Err(format!(
            "{rel}: a kit file starts with `// design: <file>:<lines> @<commit>` or `// derived: ...`"
        ));
    };
    if cite.trim().is_empty() {
        return Err(format!("{rel}: empty {how}: header"));
    }
    if how == "design"
        && let Some(src) = design
    {
        for part in cite.split(", ") {
            let file = part.split(':').next().unwrap_or("").trim();
            if !src.join(file).is_file() {
                return Err(format!("{rel}: cites {file}, not in the design clone"));
            }
        }
    }
    Ok(())
}

/// Every violation of the tree, counted per (file, rule, token).
fn violations() -> (Counts, Vec<String>) {
    let mut counts = BTreeMap::new();
    let mut hard = Vec::new();
    let design = std::env::var_os("WUBBLE_DESIGN").map(|d| PathBuf::from(d).join("src/wubble"));
    let mut add = |file: &str, rule: &str, token: String| {
        *counts
            .entry((file.to_string(), rule.to_string(), token))
            .or_insert(0) += 1;
    };
    for (rel, text) in ui_files() {
        match kind(&rel) {
            Kind::Shell => {
                for line in text.lines() {
                    for (rule, token) in shell_violations(line) {
                        add(&rel, rule, token);
                    }
                }
            }
            Kind::Kit => {
                if let Err(e) = provenance(&rel, &text, design.as_deref()) {
                    hard.push(e);
                }
                for line in text.lines() {
                    for lit in literals(line) {
                        add(&rel, "kit-literal", lit);
                    }
                }
            }
            Kind::Generated => {
                if let Err(e) = generated(&text) {
                    hard.push(format!("{rel}: {e}"));
                }
            }
            Kind::LegacyTokens => {}
        }
    }
    let shaders = repo().join("crates/wubble-gfx/src/scene/shaders");
    let mut wgsl = Vec::new();
    files(&shaders, "wgsl", &mut wgsl);
    wgsl.sort();
    for path in wgsl {
        let text = fs::read_to_string(&path).expect("read wgsl");
        if !text.starts_with("// translates: ") {
            let rel = path
                .strip_prefix(repo())
                .expect("in repo")
                .to_string_lossy();
            add(
                &rel.replace('\\', "/"),
                "shader-header",
                "translates".into(),
            );
        }
    }
    (counts, hard)
}

/// FNV-1a 64 of `text`'s bytes (the generator's `fnv1a64`).
fn fnv1a64(text: &str) -> u64 {
    text.bytes().fold(0xcbf2_9ce4_8422_2325, |h, b| {
        (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3)
    })
}

/// A generated file's two header lines hold the design commit and its body's hash.
fn generated(text: &str) -> Result<(), String> {
    let mut lines = text.splitn(3, '\n');
    let first = lines.next().unwrap_or("");
    let second = lines.next().unwrap_or("");
    let body = lines.next().unwrap_or("");
    let commit = first
        .strip_prefix("// generated by tools/fidelity/extract.mjs from ")
        .and_then(|r| r.split_whitespace().next())
        .ok_or("no `generated by tools/fidelity/extract.mjs from <commit>` header")?;
    if commit.len() < 7 || !commit.chars().all(|c| c.is_ascii_hexdigit()) {
        return Err(format!("`{commit}` is not a commit"));
    }
    let hash = second
        .strip_prefix("// body-fnv1a64: ")
        .ok_or("no body-fnv1a64 header")?;
    let actual = format!("{:016x}", fnv1a64(body));
    if hash != actual {
        return Err(format!(
            "edited by hand (body hash {actual}, header {hash}): run node tools/fidelity/extract.mjs"
        ));
    }
    Ok(())
}

fn baseline_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/kit_lock_baseline.txt")
}

fn read_baseline() -> Counts {
    let text = fs::read_to_string(baseline_path()).unwrap_or_default();
    text.lines()
        .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
        .map(|l| {
            let f: Vec<&str> = l.split('\t').collect();
            assert_eq!(f.len(), 4, "baseline line: {l}");
            (
                (f[0].to_string(), f[1].to_string(), f[2].to_string()),
                f[3].parse().expect("count"),
            )
        })
        .collect()
}

fn write_baseline(counts: &Counts) {
    let mut text = String::from(
        "# The kit lock's recorded violations (tests/kit_lock.rs): file, rule, token, count.\n\
         # Counts only go down: a lane that clears violations lowers them here (KIT_LOCK_WRITE=1).\n",
    );
    for ((file, rule, token), n) in counts {
        text.push_str(&format!("{file}\t{rule}\t{token}\t{n}\n"));
    }
    fs::write(baseline_path(), text).expect("write baseline");
}

#[test]
fn the_kit_lock_holds() {
    let (counts, hard) = violations();
    assert!(hard.is_empty(), "kit lock:\n{}", hard.join("\n"));
    // The first baseline is recorded once, when the file does not exist yet.
    if !baseline_path().exists() && std::env::var_os("KIT_LOCK_WRITE").is_some() {
        write_baseline(&counts);
    }
    let baseline = read_baseline();
    let mut grown = Vec::new();
    let mut shrunk = Vec::new();
    for (key, n) in &counts {
        let was = baseline.get(key).copied().unwrap_or(0);
        if *n > was {
            grown.push(format!(
                "{}: {} `{}`: {n} (baseline {was})",
                key.0, key.1, key.2
            ));
        }
    }
    for (key, was) in &baseline {
        let n = counts.get(key).copied().unwrap_or(0);
        if n < *was {
            shrunk.push(format!(
                "{}: {} `{}`: {n} (baseline {was})",
                key.0, key.1, key.2
            ));
        }
    }
    assert!(
        grown.is_empty(),
        "new kit-lock violations (compose kit components; values come from ui/kit/gen):\n{}",
        grown.join("\n")
    );
    if std::env::var_os("KIT_LOCK_WRITE").is_some() {
        write_baseline(&counts);
        return;
    }
    assert!(
        shrunk.is_empty(),
        "violations cleared: lower the baseline (KIT_LOCK_WRITE=1 cargo test -p wubble-ui --test kit_lock):\n{}",
        shrunk.join("\n")
    );
}

#[test]
fn scanner_flags_literals() {
    assert_eq!(literals("background: #fff;"), ["#fff"]);
    assert_eq!(literals("width: 12px;"), ["12px"]);
    assert_eq!(literals("duration: 150ms;"), ["150ms"]);
    assert!(literals("color: rgba(0, 0, 0, 1);").contains(&"rgba(".to_string()));
    assert_eq!(literals("text: \"\u{d7}\"; background: #fff;"), ["#fff"]);
    assert!(literals("x: 0px; y: Spacing.s2; // 12px #fff").is_empty());
    assert!(literals("commands: \"M3 12h18s-3.8 8.5 1s\";").is_empty());
    assert_eq!(literals("text: \"a\"; width: 3px;"), ["3px"]);
}

#[test]
fn scanner_flags_shell_drawing() {
    let rules = |l: &str| {
        shell_violations(l)
            .into_iter()
            .map(|(r, t)| format!("{r}:{t}"))
            .collect::<Vec<_>>()
    };
    assert_eq!(
        rules("    background: Palette.ink;"),
        ["paint:background", "token:Palette"]
    );
    assert_eq!(
        rules("    drop-shadow-blur: Shell.x;"),
        ["paint:drop-shadow-blur"]
    );
    assert_eq!(
        rules("    animate opacity { duration: Shell.ms; }"),
        ["animate:animate"]
    );
    assert_eq!(rules("    if a: Text {"), ["text:Text"]);
    assert_eq!(rules("    Path {"), ["primitive:Path"]);
    assert_eq!(rules("    font-size: Shell.f;"), ["font:font-size"]);
    assert!(rules("    image-fit: fill;").is_empty());
    assert!(rules("    text: \"Palette.ink Text {\"; // background: red").is_empty());
    assert!(rules("    padding: Spacing.s2; x: Chrome.inset;").is_empty());
    assert!(rules("    tier: GlassTier.thin;").is_empty());
    assert_eq!(
        rules("    Rectangle { background: Shell.x; }"),
        ["paint:background"]
    );
}

#[test]
fn generated_headers_are_checked() {
    let body = "export global A { }\n";
    let good = format!(
        "// generated by tools/fidelity/extract.mjs from 598f814 (x); do not edit\n// body-fnv1a64: {:016x}\n{body}",
        fnv1a64(body)
    );
    assert_eq!(generated(&good), Ok(()));
    assert!(generated(&good.replace("export", "exported")).is_err());
    assert!(generated("export global A { }\n").is_err());
    // the generator's FNV-1a 64 (a known vector)
    assert_eq!(fnv1a64("a"), 0xaf63_dc4c_8601_ec8c);
}

#[test]
fn kit_files_cite_the_design() {
    assert!(
        provenance(
            "kit/x.slint",
            "// design: core/wubble.css:1-9 @598f814\n",
            None
        )
        .is_ok()
    );
    assert!(provenance("kit/x.slint", "// derived: Menu(touch.tsx:458)\n", None).is_ok());
    assert!(provenance("kit/x.slint", "// Moved from components.slint\n", None).is_err());
}

/// The generated Rust constants carry the same header as the Slint ones.
#[test]
fn generated_rust_is_untouched() {
    let path = repo().join("crates/wubble-core/src/kit_gen.rs");
    let text = fs::read_to_string(path).expect("read kit_gen.rs");
    assert_eq!(generated(&text), Ok(()));
}

/// Focus and selection show by fill and the touch sheen, never a border:
/// no `border-color` within three lines of a focus test.
#[test]
fn no_focus_borders() {
    let mut violations = Vec::new();
    for (rel, text) in ui_files() {
        let lines: Vec<&str> = text.lines().collect();
        for (n, line) in lines.iter().enumerate() {
            if !line.contains("border-color") {
                continue;
            }
            let near = &lines[n.saturating_sub(3)..(n + 4).min(lines.len())];
            if near
                .iter()
                .any(|l| l.contains("has-focus") || l.contains("focused when"))
            {
                violations.push(format!("{rel}:{}", n + 1));
            }
        }
    }
    assert!(
        violations.is_empty(),
        "focus borders:\n{}",
        violations.join("\n")
    );
}

/// No squircle with a letter anywhere: no glyph tiles or glyph fields.
#[test]
fn no_letter_tiles() {
    let mut violations = Vec::new();
    for (rel, text) in ui_files() {
        for (n, line) in text.lines().enumerate() {
            let code = line.split("//").next().unwrap_or("");
            let words = code.split(|c: char| !(c.is_alphanumeric() || c == '-' || c == '_'));
            for word in words {
                if matches!(word, "glyph" | "GlyphTile" | "PinnedTile" | "SpaceDot") {
                    violations.push(format!("{rel}:{}: {word}", n + 1));
                }
            }
        }
    }
    assert!(
        violations.is_empty(),
        "letter tiles:\n{}",
        violations.join("\n")
    );
}
